    insufficientDataBody: "விலைப் போக்கை மதிப்பிட குறைந்தது தொடர்ந்து 7 நாட்களின் சரிபார்க்கப்பட்ட விலைகள் தேவை. உள்ளூர் APMCயின் தற்போதைய விலையைச் சரிபார்க்கவும்.",
    risingAdviceBody: "சமீபத்திய 3 நாள் சராசரி (₹{avg3}/குவிண்டால்), 7 நாள் சராசரியை (₹{avg7}/குவிண்டால்) விட அதிகம். சுத்தமான, உலர்ந்த பாதுகாப்பான சேமிப்பு இருந்தால் அதிகபட்சம் {days} நாட்கள் காத்திருக்கலாம். சேமிப்புச் செலவு நாளுக்கு ₹{cost}.",
    fallingAdviceBody: "சமீபத்திய 3 நாள் சராசரி (₹{avg3}/குவிண்டால்), 7 நாள் சராசரியை (₹{avg7}/குவிண்டால்) விடக் குறைவு. விலை வீழும்போது காத்திருப்பது நாளுக்கு சுமார் ₹{cost} சேமிப்புச் செலவைச் சேர்க்கும்.",
    mixedAdviceBody: "3 நாள் மற்றும் 7 நாள் விலைகள் நிலையாக அல்லது தெளிவான திசையின்றி மாறுகின்றன. போக்குவரத்தை ஏற்பாடு செய்வதற்கு முன் உள்ளூர் வணிகர் விலைகளையும் அருகிலுள்ள மண்டிகளின் நிகர வருமானத்தையும் ஒப்பிடுங்கள்.",
