export const DICTS: Record<Lang, Dict> = {
  en: { ...en, ...routeCopy.en },
  kn: { ...kn, ...routeCopy.kn },
  hi: { ...hi, ...routeCopy.hi },
  ta: { ...ta, ...routeCopy.ta },
  te: { ...te, ...routeCopy.te },
  mr: { ...mr, ...routeCopy.mr },
};

export function locationLabel(
  location: { state: string; district: string; village: string } | null,
  dict: Dict,
): string {
  if (!location) return dict.currentLocation;
  const isGpsLocation =
    location.state === "__gps_detected__" ||
    location.village === "__current_location__" ||
    location.state === "Detected (GPS)" ||
    Object.values(DICTS).some(
      (locale) =>
        locale.locationDetected === location.state || locale.currentLocation === location.village,
    );
  return isGpsLocation ? dict.currentLocation : location.village || location.district;
}

export function fmt(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (_, k) => String(values[k] ?? `{${k}}`));
}
